UPDATE crm_deal_team SET allocated_amount = #{row.allocatedAmount}, commission_amount = #{row.commissionAmount},
    update_by = #{row.updateBy}, update_time = #{row.updateTime}
WHERE tenant_id = #{row.tenantId} AND biz_type = 'CONTRACT' AND biz_id = #{row.bizId}
    AND team_version = #{row.teamVersion} AND team_id = #{row.teamId} AND current_flag = 1
